Las ranuras viven en un vector, con una lista libre de índices reciclados:

```cpp
struct Handle { std::uint32_t index, generation; };

struct EnemyPool {
    struct Slot { Enemy enemy; std::uint32_t generation = 0; bool used = false; };
    std::vector<Slot> slots;
    std::vector<std::uint32_t> freeList;

    Handle spawn(Enemy e) {
        std::uint32_t i;
        if (!freeList.empty()) { i = freeList.back(); freeList.pop_back(); }
        else { i = (std::uint32_t)slots.size(); slots.emplace_back(); }
        slots[i].enemy = e;
        slots[i].used = true;
        return {i, slots[i].generation};
    }
    void destroy(Handle h) {
        if (!get(h)) return;
        slots[h.index].used = false;
        slots[h.index].generation++;
        freeList.push_back(h.index);
    }
    Enemy* get(Handle h) {
        if (h.index >= slots.size()) return nullptr;
        Slot& s = slots[h.index];
        if (s.generation != h.generation || !s.used) return nullptr;
        return &s.enemy;
    }
};
```

